import{_ as l,c as e,o as t,al as r}from"./chunks/framework.QMC68jD7.js";const _=JSON.parse('{"title":"charles抓包工具的作用","description":"","frontmatter":{"layoutClass":"m-nav-layout"},"headers":[],"relativePath":"tech/javascript/15-用charles抓包数据.md","filePath":"tech/javascript/15-用charles抓包数据.md","lastUpdated":1777268227000}'),i={name:"tech/javascript/15-用charles抓包数据.md"};function s(o,a,p,c,h,n){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="charles抓包工具的作用" tabindex="-1">charles抓包工具的作用 <a class="header-anchor" href="#charles抓包工具的作用" aria-label="Permalink to &quot;charles抓包工具的作用&quot;">​</a></h1><p>Charles是一个用于抓包的好工具，Charles抓包是通过中间人代理实现，在客户端和服务端通信时，Charles会截取客户端发送给服务端的请求，然后伪装成客户端与服务端进行通信，服务端返回数据时，Charles会截取数据伪装成服务端将数据发送给客户端。</p><ul><li>参考：手把手教你如何使用Charles抓包</li></ul><p><a href="https://blog.csdn.net/caixiangting/article/details/125646494" target="_blank" rel="noreferrer">https://blog.csdn.net/caixiangting/article/details/125646494</a></p><h1 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to &quot;下载安装&quot;">​</a></h1><p>下载地址： <a href="https://www.charlesproxy.com/" target="_blank" rel="noreferrer">https://www.charlesproxy.com/</a></p><h1 id="charles配置" tabindex="-1">charles配置 <a class="header-anchor" href="#charles配置" aria-label="Permalink to &quot;charles配置&quot;">​</a></h1><p>如果需要抓取https协议的包，需要进行配置</p><ol><li>点击顶部菜单栏【Help】–&gt;选择【SSL Proxying】，点击【install Charles Root Certificate 】安装Charles根证书即可</li></ol><p><img src="https://img-blog.csdnimg.cn/img_convert/c5eacb0cb7041d8dbb8479ed87c4b015.png" alt="img"></p><ol start="2"><li>单击“安装证书”，出现以下界面</li></ol><p>（截图资源缺失，暂不展示）</p><ol start="3"><li><p>选择“本地计算机&quot;, 然后”下一页“</p><p>（截图资源缺失，暂不展示）</p></li><li><p>选择&quot;将所有证书都放入下列存储&quot;，并单击”浏览“, 在弹出窗口中选择”受信任的根证书颁发机构&quot;,并确定，然后单击“下一步”</p></li></ol><p>（截图资源缺失，暂不展示）</p><ol start="5"><li><p>在下方窗口中单击“完成” （截图资源缺失，暂不展示）</p></li><li><p>显示导入成功</p><p>（截图资源缺失，暂不展示）</p></li><li><p>关闭charles后重启，再执行第一步的指令，显示下图,说明证书安装成功, 单击“确定”关闭即可</p><p>（截图资源缺失，暂不展示）</p></li></ol><h1 id="使用charles获取数据" tabindex="-1">使用charles获取数据 <a class="header-anchor" href="#使用charles获取数据" aria-label="Permalink to &quot;使用charles获取数据&quot;">​</a></h1><ol><li><p>打开charles</p></li><li><p>用浏览器访问网页</p></li><li><p>在charles中会显示访问的域名列表</p></li><li><p>选择要抓包的域名，在右侧切换到&quot;Summary&quot;, 查看&quot;Mime Type&quot;为 &quot;application/json&quot; 即响应数据为json</p><p>（截图资源缺失，暂不展示）</p></li><li><p>双击summary中某一项</p></li><li><p>（截图资源缺失，暂不展示）</p></li></ol>',17)])])}const u=l(i,[["render",s]]);export{_ as __pageData,u as default};
